args <- commandArgs(trailingOnly=TRUE)
if(length(args)<3) stop("Usage: Rscript script full.csv mri.csv output_dir")
full_path<-args[1]; mri_path<-args[2]; out_dir<-args[3]
dir.create(out_dir,recursive=TRUE,showWarnings=FALSE)
options(stringsAsFactors=FALSE,warn=1)
suppressPackageStartupMessages(library(survival)); suppressPackageStartupMessages(library(splines))
save_csv<-function(x,n) write.csv(x,file.path(out_dir,n),row.names=FALSE,na="",fileEncoding="UTF-8")
zscore<-function(x){x<-as.numeric(x);s<-sd(x,na.rm=TRUE);if(!is.finite(s)||s==0)return(rep(NA_real_,length(x)));as.numeric((x-mean(x,na.rm=TRUE))/s)}
eth4<-function(x){x<-tolower(trimws(as.character(x)));w<-x%in%c("british","irish","white","any other white background");a<-x%in%c("indian","pakistani","bangladeshi","chinese","asian or asian british","any other asian background");b<-x%in%c("caribbean","african","black or black british","any other black background");factor(ifelse(w,"White",ifelse(a,"Asian",ifelse(b,"Black","Other/unknown"))),levels=c("White","Asian","Black","Other/unknown"))}
vcov_hc3<-function(f){X0<-model.matrix(f);k<-!is.na(coef(f));X<-X0[,k,drop=F];u<-residuals(f);h<-pmin(hatvalues(f),.999999);WX<-X*(u/(1-h));B<-tryCatch(solve(crossprod(X)),error=function(e)NULL);if(is.null(B))return(vcov(f)[k,k,drop=F]);V<-B%*%crossprod(WX)%*%B;dimnames(V)<-list(colnames(X),colnames(X));V}
tidy_lm<-function(f,t,m,c){b<-coef(f)[t];se<-sqrt(vcov_hc3(f)[t,t]);data.frame(outcome="BAG",model=m,component=c,term=t,estimate=unname(b),se=unname(se),CI_low=unname(b-1.96*se),CI_high=unname(b+1.96*se),HR=NA_real_,p=unname(2*pnorm(-abs(b/se))),n=nobs(f),events=NA_integer_,effect_type="Beta_years")}
tidy_cox<-function(f,t,m,c){b<-coef(f)[t];se<-sqrt(vcov(f)[t,t]);data.frame(outcome="Incident_CKD",model=m,component=c,term=t,estimate=unname(b),se=unname(se),CI_low=unname(exp(b-1.96*se)),CI_high=unname(exp(b+1.96*se)),HR=unname(exp(b)),p=unname(2*pnorm(-abs(b/se))),n=f$n,events=f$nevent,effect_type="Hazard_ratio")}
cat("Reading V2 cohorts...\n")
full<-read.csv(full_path,check.names=F,na.strings=c("","NA"));mri<-read.csv(mri_path,check.names=F,na.strings=c("","NA"))
stopifnot(!anyDuplicated(full$participant_id),!anyDuplicated(mri$participant_id))
full$baseline_date_r<-as.Date(substr(full$baseline_date,1,10));full$time0_full_r<-as.Date(substr(full$time0_full,1,10));full$age_webq<-as.numeric(full$Age_at_recruitment)+as.numeric(full$time0_full_r-full$baseline_date_r)/365.25
full$sex_factor<-relevel(factor(full$Sex),ref="Female");full$ethnicity4<-eth4(full$Ethnic_0);full$tdi<-as.numeric(full$TDI_at_recruitment);full$edu_z<-as.numeric(full$area_education_deprivation_z);full$edu_missing<-factor(ifelse(is.na(full$edu_z),"Missing","Observed"),levels=c("Observed","Missing"));full$edu_z_imp<-ifelse(is.na(full$edu_z),0,full$edu_z);full$baseline_center_factor<-factor(full$baseline_center);full$energy_z<-zscore(full$energy_kcal_primary);full$webq_rounds<-as.numeric(full$webq_n_dates)
mri$sex_factor<-relevel(factor(mri$Sex),ref="Female");mri$ethnicity4<-eth4(mri$Ethnic_0);mri$tdi<-as.numeric(mri$TDI_at_recruitment);mri$edu_z<-as.numeric(mri$area_education_deprivation_z);mri$edu_missing<-factor(ifelse(is.na(mri$edu_z),"Missing","Observed"),levels=c("Observed","Missing"));mri$edu_z_imp<-ifelse(is.na(mri$edu_z),0,mri$edu_z);mri$center<-factor(mri$v4);mri$energy_z<-zscore(mri$energy_kcal_pre_mri_mean);mri$gap_years<-as.numeric(mri$webq_mri_gap_days)/365.25;mri$v_scaling_z<-zscore(mri$v_scaling_t1_to_standard_2);mri$scanner_x_z<-zscore(mri$scanner_lateral_x_brain_2);mri$scanner_y_z<-zscore(mri$scanner_transverse_y_brain_2);mri$scanner_z_z<-zscore(mri$scanner_longitudinal_z_brain_2);mri$scanner_table_z<-zscore(mri$scanner_table_position_2);mri$t2flair_qc<-factor(mri$t2flair_run_freesurfer_2)
components<-c("le8_diet_primary","le8_pa","le8_nicotine","le8_sleep","le8_bmi","le8_nonhdl","le8_glucose","le8_bp")
labels<-setNames(c("Diet","Physical_activity","Nicotine_exposure","Sleep","BMI","Non_HDL_cholesterol","Blood_glucose","Blood_pressure"),components)
for(v in components){full[[paste0(v,"_per10")]]<-as.numeric(full[[v]])/10;mri[[paste0(v,"_per10")]]<-as.numeric(mri[[v]])/10}
full_cov<-"age_webq+sex_factor+ethnicity4+tdi+edu_z_imp+edu_missing+baseline_center_factor+energy_z+webq_rounds"
bag_cov<-"age+sex_factor+ethnicity4+tdi+edu_z_imp+edu_missing+center+energy_z+gap_years+v_scaling_z+scanner_x_z+scanner_y_z+scanner_z_z+scanner_table_z+t2flair_qc"
terms<-paste0(components,"_per10")
bag_fit<-lm(as.formula(paste("brain_age_gap_oos_candidate~",paste(terms,collapse="+"),"+",bag_cov)),data=mri)
ckd_fit<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~",paste(terms,collapse="+"),"+",full_cov)),data=full)
bag_res<-lapply(seq_along(terms),function(i)tidy_lm(bag_fit,terms[i],"Mutually_adjusted_8_components",labels[components[i]]))
ckd_res<-lapply(seq_along(terms),function(i)tidy_cox(ckd_fit,terms[i],"Mutually_adjusted_8_components",labels[components[i]]))
res<-rbind(do.call(rbind,bag_res),do.call(rbind,ckd_res));res$p_FDR<-ave(res$p,res$outcome,FUN=function(x)p.adjust(x,"BH"));res$scale<-"per_10_points"
save_csv(res,"Table_P1_component_association_profiles.csv")
cat("Running total and domain models...\n")
full$LE8_per10<-as.numeric(full$LE8)/10;full$LE8_legacy_do_per10<-as.numeric(full$LE8_legacy_do)/10;mri$LE8_per10<-as.numeric(mri$LE8)/10;mri$LE8_legacy_do_per10<-as.numeric(mri$LE8_legacy_do)/10
flm<-function(y,x,n){f<-lm(as.formula(paste(y,"~",x,"+",bag_cov)),data=mri);tidy_lm(f,x,n,"Total_LE8")};fcx<-function(x,n){f<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~",x,"+",full_cov)),data=full);tidy_cox(f,x,n,"Total_LE8")}
tot<-rbind(flm("brain_age_gap_oos_candidate","LE8_per10","Primary_OOS_BAG_AHA_LE8"),flm("brain_age_gap_final_model","LE8_per10","Sensitivity_final_BAG_AHA_LE8"),flm("brain_age_gap_oos_candidate","LE8_legacy_do_per10","Sensitivity_OOS_BAG_legacy_LE8"),fcx("LE8_per10","Primary_CKD_AHA_LE8"),fcx("LE8_legacy_do_per10","Sensitivity_CKD_legacy_LE8"));tot$scale<-"per_10_points";save_csv(tot,"Table_P1_total_LE8_models.csv")
for(v in c("LE8_behavior","LE8_biological")){full[[paste0(v,"_per10")]]<-as.numeric(full[[v]])/10;mri[[paste0(v,"_per10")]]<-as.numeric(mri[[v]])/10}
dlm<-lm(as.formula(paste("brain_age_gap_oos_candidate~LE8_behavior_per10+LE8_biological_per10+",bag_cov)),data=mri);dcx<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~LE8_behavior_per10+LE8_biological_per10+",full_cov)),data=full)
dom<-rbind(tidy_lm(dlm,"LE8_behavior_per10","Behavior_biological_mutual","Behavior_domain"),tidy_lm(dlm,"LE8_biological_per10","Behavior_biological_mutual","Biological_domain"),tidy_cox(dcx,"LE8_behavior_per10","Behavior_biological_mutual","Behavior_domain"),tidy_cox(dcx,"LE8_biological_per10","Behavior_biological_mutual","Biological_domain"));dom$p_FDR<-ave(dom$p,dom$outcome,FUN=function(x)p.adjust(x,"BH"));dom$scale<-"per_10_points";save_csv(dom,"Table_P1_behavior_biological_domains.csv")
cat("Running non-HDL audit...\n")
full$legacy_nonhdl_per10<-as.numeric(full$le8_nonhdl_legacy_do)/10;mri$legacy_nonhdl_per10<-as.numeric(mri$le8_nonhdl_legacy_do)/10;full$nonhdl_raw_sd<-zscore(full$non_hdl_mgdl);mri$nonhdl_raw_sd<-zscore(mri$non_hdl_mgdl);full$lipid_med_factor<-factor(full$lipid_lowering_med);mri$lipid_med_factor<-factor(mri$lipid_lowering_med)
b1<-lm(as.formula(paste("brain_age_gap_oos_candidate~le8_nonhdl_per10+",bag_cov)),data=mri);b2<-lm(as.formula(paste("brain_age_gap_oos_candidate~legacy_nonhdl_per10+lipid_med_factor+",bag_cov)),data=mri);b3<-lm(as.formula(paste("brain_age_gap_oos_candidate~nonhdl_raw_sd+",bag_cov)),data=mri[mri$lipid_lowering_med==0,]);c1<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~le8_nonhdl_per10+",full_cov)),data=full);c2<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~legacy_nonhdl_per10+lipid_med_factor+",full_cov)),data=full);c3<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~nonhdl_raw_sd+",full_cov)),data=full[full$lipid_lowering_med==0,])
nh<-rbind(tidy_lm(b1,"le8_nonhdl_per10","AHA_treatment_adjusted_score","Non_HDL"),tidy_lm(b2,"legacy_nonhdl_per10","Legacy_score_plus_medication","Non_HDL"),tidy_lm(b3,"nonhdl_raw_sd","Raw_nonHDL_untreated_only","Non_HDL"),tidy_cox(c1,"le8_nonhdl_per10","AHA_treatment_adjusted_score","Non_HDL"),tidy_cox(c2,"legacy_nonhdl_per10","Legacy_score_plus_medication","Non_HDL"),tidy_cox(c3,"nonhdl_raw_sd","Raw_nonHDL_untreated_only","Non_HDL"));nh$scale<-c("per_10_points","per_10_points","per_SD_raw_mgdl","per_10_points","per_10_points","per_SD_raw_mgdl");save_csv(nh,"Table_P1_nonHDL_direction_audit.csv")
cat("Running nonlinearity tests...\n")
blin<-lm(as.formula(paste("brain_age_gap_oos_candidate~LE8_per10+",bag_cov)),data=mri);bspl<-lm(as.formula(paste("brain_age_gap_oos_candidate~ns(LE8_per10,df=4)+",bag_cov)),data=mri);clin<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~LE8_per10+",full_cov)),data=full);cspl<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~ns(LE8_per10,df=4)+",full_cov)),data=full);ba<-anova(blin,bspl);lr<-2*(as.numeric(logLik(cspl))-as.numeric(logLik(clin)));nl<-data.frame(outcome=c("BAG","Incident_CKD"),comparison="Linear_vs_4df_spline",statistic=c(ba$F[2],lr),df=c(ba$Df[2],3),p=c(ba$`Pr(>F)`[2],pchisq(lr,3,lower.tail=F)));save_csv(nl,"Table_P1_total_LE8_nonlinearity_tests.csv")
inv<-data.frame(item=c("Frozen full cohort","Frozen MRI cohort","Primary OOS BAG available","Full CKD events","MRI postscan CKD events","Full lipid-lowering medication","MRI lipid-lowering medication"),n=c(nrow(full),nrow(mri),sum(!is.na(mri$brain_age_gap_oos_candidate)),sum(full$kidney_event),sum(mri$kidney_event_mri),sum(full$lipid_lowering_med==1),sum(mri$lipid_lowering_med==1)));save_csv(inv,"P1_analysis_sample_inventory.csv")
